def question(cat,lang):
    policy,criteria=POL[cat][lang]
    return {'decision':{'type':'choice','instructions':(G_DE if lang=='de' else G_EN)+policy,'criteria':criteria}}
def write_jsonl(name,rows):
    (D/name).write_text(''.join(json.dumps(r,ensure_ascii=False,separators=(',',':'))+'\n' for r in rows),encoding='utf-8')

def main():
    if (D/'freeze_manifest.json').exists():
        raise SystemExit('Frozen benchmark: do not rebuild in place. Create and document a new version.')
    cases=[];pairs=[]
    for cat,rows in DATA.items():
        assert len(rows)==10
        counts=collections.Counter(r[0] for r in rows)
        assert set(counts)==set(POL[cat]['de'][1]) and set(counts.values())=={2}
        assert list(POL[cat]['de'][1])==list(POL[cat]['en'][1])
        for i,(label,de,tags,rationale,en) in enumerate(rows,1):
            stem=f'finance_{cat}_{i:03d}';pair_id=f'pair_{stem}' if en else None
            base={'category':cat,'expected':{'decision':label},'tags':tags.split(','),'pair_id':pair_id,'gold_rationale':rationale}
            cases.append(dict(base,id=f'de_{stem}',language='de',schema_language='de',split='german_primary',input=de,questions=question(cat,'de')))
            if en:
                cases.append(dict(base,id=f'en_{stem}',language='en',schema_language='en',split='english_control',input=en,questions=question(cat,'en')))
                pairs.append({'pair_id':pair_id,'category':cat,'german_id':f'de_{stem}','english_id':f'en_{stem}'})
    assert len(cases)==100 and len(pairs)==20
    write_jsonl('cases.jsonl',cases)
    write_jsonl('diagnostic_cases.jsonl',[])
    write_jsonl('pairs.jsonl',pairs)
    randomized=cases.copy();random.Random(2026100202).shuffle(randomized)
    write_jsonl('requests.jsonl',[{'id':c['id'],'request':{'model':'clef-flash','state':c['input'],'questions':c['questions']}} for c in randomized])
    write_jsonl('gold.jsonl',[{k:c[k] for k in ('id','category','language','schema_language','split','expected','tags','pair_id','gold_rationale')} for c in randomized])
    (D/'policies.json').write_text(json.dumps({cat:{lang:question(cat,lang) for lang in ('de','en')} for cat in POL},ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    summary={'benchmark_version':'finance-broker-v1','primary_german':80,'english_controls':20,'mixed_schema_diagnostic':0,'total_requests':100,'random_order_seed':2026100202,'categories':{cat:dict(collections.Counter(row[0] for row in rows)) for cat,rows in DATA.items()},'german_tag_counts':dict(collections.Counter(tag for rows in DATA.values() for row in rows for tag in row[2].split(','))),'english_pair_selection':'Deliberate challenge coverage: three pairs in each of first four categories, two in each of last four; not every class is represented in English. Paired comparisons only on these 20 cases.','chance_reference_accuracy':0.2,'real_personal_data':False,'real_legal_rules':False}
    (D/'design_summary.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    print(json.dumps(summary,ensure_ascii=False,indent=2))
if __name__=='__main__':main()
